package com.fincore.fincore.admin; import java.util.List; import org.springframework.web.bind.annotation.*; import com.fincore.fincore.user.*; @RestController @RequestMapping("/api/v1/admin/users") public class AdminController{private final UserRepository users;public AdminController(UserRepository u){users=u;}@GetMapping public List<UserResponse> all(){return users.findAll().stream().map(UserResponse::from).toList();}@GetMapping("/{id}")public UserResponse one(@PathVariable Long id){return users.findById(id).map(UserResponse::from).orElseThrow(()->new com.fincore.fincore.exception.NotFoundException("User not found"));}}
